                                    "type": "string"
                                }
                            }
                        ]
                    },
                    "description": "Any user attributes (OR logic) for accessing this model"
                },
                "group_details": {
                    "type": "object",
                    "additionalProperties": {
                        "type": "object",
                        "properties": {
                            "label": {
                                "type": "string"
                            },
