                                "type": "string"
                            },
                            "ai_hint": {
                                "oneOf": [
                                    {
                                        "type": "string"
                                    },
                                    {
                                        "type": "array",
                                        "items": {
                                            "type": "string"
                                        }
                                    }
                                ],
                                "description": "Hints inherited by fields in this group for AI-powered query generation"
                            }
                        },
                        "required": ["label"]
                    },
                    "description": "Metadata for field groups"
                },
                "sets": {
                    "type": "object",
                    "additionalProperties": {
                        "type": "object",
                        "properties": {
                            "label": {
                                "type": "string"
                            },
                            "description": {
                                "type": "string"
                            },
                            "fields": {
                                "type": "array",
                                "items": {
                                    "type": "string"
                                }
                            }
                        }
                    },
                    "description": "Named sets of fields for quick selection"
