                        {
                            "type": "array",
                            "items": {
                                "type": "string"
                            }
                        }
                    ],
                    "description": "Hints for AI-powered query generation"
                },
                "parameters": {
                    "type": "object",
                    "description": "Dynamic parameters for the model"
